import{_ as e,c as r,o as d,b0 as a}from"./chunks/framework.Becqh7-x.js";const _=JSON.parse('{"title":"LV015-运行模型","description":null,"frontmatter":{"title":"LV015-运行模型","date":"2026-01-06T14:48:53.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/platform/cortexA7/126d2c6e0c550a64cbda4911","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T14:48:53.166Z","fulluuid":"4cbda491166c4ae3b4310f88d9f4cae4","useduuid":"4cbda4911"}},"headers":[],"relativePath":"sdoc/platform/cortexA7/126d2c6e0c550a64cbda4911.md","filePath":"sdoc/10-开发平台/10-Cortex-A7/LV015-A7运行模型.md","lastUpdated":1768604092000}'),l={name:"sdoc/platform/cortexA7/126d2c6e0c550a64cbda4911.md"};function n(o,t,c,s,i,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="lv015-运行模型" tabindex="-1">LV015-运行模型 <a class="header-anchor" href="#lv015-运行模型" aria-label="Permalink to &quot;LV015-运行模型&quot;">​</a></h1><p>以前的 ARM 处理器有 7 中运行模型： User、 FIQ、 IRQ、 Supervisor(SVC)、 Abort、 Undef 和 System，其中 User 是非特权模式，其余 6 种都是特权模式。但新的 Cortex-A 架构加入了 TrustZone 安全扩展，所以就新加了一种运行模式： Monitor，新的处理器架构还支持虚拟化扩展，因此又加入了另一个运行模式： Hyp，所以 Cortex-A7 处理器有 9 种处理模式，如表所示：</p><table tabindex="0"><thead><tr><th style="text-align:center;">模式</th><th>描述</th></tr></thead><tbody><tr><td style="text-align:center;">User(USR)</td><td>用户模式，非特权模式，大部分程序运行的时候就处于此模式。</td></tr><tr><td style="text-align:center;">FIQ</td><td>快速中断模式，进入 FIQ 中断异常</td></tr><tr><td style="text-align:center;">IRQ</td><td>一般中断模式。</td></tr><tr><td style="text-align:center;">Supervisor(SVC)</td><td>超级管理员模式，特权模式，供操作系统使用。</td></tr><tr><td style="text-align:center;">Monitor(MON)</td><td>这个模式用于安全扩展模式。</td></tr><tr><td style="text-align:center;">Abort(ABT)</td><td>数据访问终止模式，用于虚拟存储以及存储保护。</td></tr><tr><td style="text-align:center;">Hyp(HYP)</td><td>用于虚拟化扩展。</td></tr><tr><td style="text-align:center;">Undef(UND)</td><td>未定义指令终止模式。</td></tr><tr><td style="text-align:center;">System(SYS)</td><td>系统模式，用于运行特权级的操作系统任务</td></tr></tbody></table><p>除了 User(USR)用户模式以外，其它 8 种运行模式都是特权模式。这几个运行模式可以通过软件进行任意切换，也可以通过中断或者异常来进行切换。所谓“运行模式”，可以这样简单理解：</p><p>（1）板子上电时， CPU 处于 SVC 模式，它用的是 SVC 模式下的寄存器。</p><p>（2）程序运行时发生了中断， CPU 进入 IRQ 模式，它用的 IRQ 模式下的寄存器。</p><p>（3）CPU 处理完中断，它切换回 SVC 模式，继续使用 SVC 模式下的寄存器。</p><p>（4）CPU 发生某种异常时，比如读取内存出错，它会进入 ABT 模式，使用 ABT 模式下的寄存器来处理错误。</p><p>大多数的程序都运行在用户模式，用户模式下是不能访问系统所有资源的，有些资源是受限的，要想访问这些受限的资源就必须进行模式切换。但是用户模式是不能直接进行切换的，<strong>用户模式下需要借助异常来完成模式切换</strong>，当要切换模式的时候，应用程序可以产生异常，在异常的处理过程中完成处理器模式切换。</p><p>当中断或者异常发生以后，处理器就会进入到相应的异常模式中，每一种模式都有一组寄存器供异常处理程序使用，这样的目的是为了保证在进入异常模式以后，用户模式下的寄存器不会被破坏。</p>',10)])])}const x=e(l,[["render",n]]);export{_ as __pageData,x as default};
